/// frame of a pre-encoded body of message `id` (forwarding without re-encoding)
pub fn frame_raw(id: u16, body: &[u8]) -> R<Vec<u8>> {
    if body.len() > MAX_FRAME as usize {
        return fail(CONTRACT, format!("frame too large {}", body.len()));
    }
    let mut b = Vec::with_capacity(HEADER + body.len());
    b.extend_from_slice(&header(MAGIC, VERSION, id, body.len() as u32));
    b.extend_from_slice(body);
    Ok(b)
}

/// stream framer of this contract; `max` lowers the body limit (e.g. 64 KiB for client->gateway)
pub fn framer(max: Option<u32>) -> Framer {
    Framer::new(MAGIC, VERSION, max.unwrap_or(MAX_FRAME), is_known)
}
